'admin.services.update',$s) }}" style="padding:18px">@csrf @method('PUT')<div class="formgrid"><div><label>Nom principal</label><input name="name" value="{{ $s->name }}" required></div><div><label>Photo</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></div><div><label>Catégorie</label><select name="service_category_id">@foreach($categories as $category)<option value="{{ $category->id }}" @selected($s->service_category_id===$category->id)>{{ $category->name }}</option>@endforeach</select></div><div><label>Prix (€)</label><input name="price" type="number" min="0" step=".01" value="{{ $s->price }}" required></div><div><label>Durée (minutes)</label><input name="duration_minutes" type="number" min="15" max="600" value="{{ $s->duration_minutes }}" required></div><div><label>Frais domicile (€)</label><input name="travel_fee" type="number" min="0" step=".01" value="{{ $s->travel_fee }}"></div><div><label>Ordre</label><input name="sort_order" type="number" min="0" value="{{ $s->sort_order }}"></div></div><label>Description principale</label><textarea name="description" rows="2">{{ $s->description }}</textarea><div class="formgrid"><div><label>Nom allemand</label><input name="name_de" value="{{ $s->name_de }}"></div><div><label>Nom français</label><input name="name_fr" value="{{ $s->name_fr }}"></div><div><label>Nom anglais</label><input name="name_en" value="{{ $s->name_en }}"></div></div><div class="formgrid"><div><label>Description allemande</label><textarea name="description_de" rows="2">{{ $s->description_de }}</textarea></div><div><label>Description française</label><textarea name="description_fr" rows="2">{{ $s->description_fr }}</textarea></div><div><label>Description anglaise</label><textarea name="description_en" rows="2">{{ $s->description_en }}</textarea></div></div><label>Conditions</label><textarea name="conditions" rows="2">{{ $s->conditions }}</textarea><div class="row"><label><input type="checkbox" name="at_salon" value="1" @checked($s->at_salon)> Au salon</label><label><input type="checkbox" name="at_home" value="1" @checked($s->at_home)> À domicile</label><label><input type="checkbox" name="price_from" value="1" @checked($s->price_from)> Prix « à partir de »</label><label><input type="checkbox" name="is_active" value="1" @checked($s->is_active)> Active</label></div><div class="form-actions"><button type="button" class="secondary" onclick="this.closest('dialog').close()">Annuler</button><button type="submit">Enregistrer les modifications</button></div></form></dialog><form method="post" action="{{ route('admin.services.destroy',$s) }}" onsubmit="return confirm('Supprimer ou désactiver cette prestation ?')">@csrf @method('DELETE')<button type="submit" class="danger icon-action" title="Supprimer ou désactiver" aria-label="Supprimer ou désactiver"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4h8v2m3 0-1 14H6L5 6m4 4v6m6-6v6"/></svg></button></form></div></td></tr>@empty<tr><td colspan="8">Aucune prestation enregistrée. Créez votre premier modèle ci-dessus.</td></tr>@endforelse</tbody></table></div></section>
<script>
(()=>{const button=document.getElementById('translate-service-button');if(!button)return;const source=document.getElementById('translation-source'),name=document.getElementById('translation-name'),description=document.getElementById('translation-description'),feedback=document.getElementById('translation-feedback');const token=document.querySelector('meta[name="csrf-token"]')?.content||document.querySelector('input[name="_token"]')?.value;const url=@json(route('admin.translation.translate'));async function translate(text,lang){if(!text.trim())return {};const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token,'X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({text,source:lang})});const data=await r.json();if(!r.ok)throw new Error(data.message||'Traduction impossible');return data.translations||{}}button.addEventListener('click',async()=>{button.disabled=true;button.textContent='Traduction en cours…';feedback.textContent='';try{const lang=source.value,n=await translate(name.value,lang),d=await translate(description.value,lang);const map={de:['name_de','description_de'],fr:['name_fr','description_fr'],en:['name_en','description_en']};const createForm=document.querySelector('form[action="{{ route('admin.services.store') }}"]');if(createForm){createForm.querySelector('[name="name"]').value=name.value;createForm.querySelector('[name="description"]').value=description.value}for(const target of ['de','fr','en']){if(target===lang)continue;const [nf,df]=map[target];if(createForm){const ni=createForm.querySelector(`[name="${nf}"]`),di=createForm.querySelector(`[name="${df}"]`);if(ni&&n[target]!==undefined)ni.value=n[target];if(di&&d[target]!==undefined)di.value=d[target]}}feedback.textContent='Traductions générées. Vérifiez-les avant l’enregistrement.'}catch(e){feedback.textContent=e.message}finally{button.disabled=false;button.textContent='Traduire vers les deux autres langues'}})})();
</script>
